///
/// Derived schema must equal `generated::protocol_schemas::arguments_location_schema()`.
#[derive(Debug, Clone, VgiArrow)]
pub struct ArgumentsLocation {
    /// The sealed reference returned by the worker's upload grant (opaque to the client;
    /// vgi-rpc ARGREF).
    pub r#ref: Bytes,
    /// Byte length of the uploaded arguments IPC stream, at least 1.
    pub size: i64,
    /// SHA-256 of exactly those bytes, as 64 lowercase hex digits.
    pub sha256: String,
}

impl ArgumentsLocation {
    /// `size` must be at least 1 and `sha256` 64 lowercase hex digits; anything
    /// else is `invalid_arguments_ref` (`INVALID_ARGUMENT`).
    pub fn validate(&self) -> ::vgi_rpc::Result<()> {
        let refuse = |message: &str| {
            Err(::vgi_rpc::RpcError::value_error(message)
                .with_status(::vgi_rpc::Code::InvalidArgument, "invalid_arguments_ref"))
        };
        if self.size < 1 {
            return refuse("arguments_location.size must be a positive byte count");
        }
        if self.sha256.len() != 64
            || !self
                .sha256
                .bytes()
                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
        {
            return refuse("arguments_location.sha256 must be 64 lowercase hex digits");
        }
        Ok(())
    }
}

/// Consolidated bind request for all function types.
///
/// For table functions (no input schema), `input_schema` is `None`. For scalar and
/// table-in-out functions, `input_schema` is set.
///
/// Exactly one of `arguments` and `arguments_location` is set; anything else is refused as
/// `invalid_bind_request` (`INVALID_ARGUMENT`).
///
/// Derived schema must equal `generated::protocol_schemas::bind_request_schema()`.
#[derive(Debug, Clone, VgiArrow)]
pub struct BindRequest {
    /// Registered name of the VGI function this message targets.
    pub function_name: String,
    /// The bound function `Arguments`; `None` when they were externalized and
    /// `arguments_location` says where they live.
    pub arguments: Option<Bytes>,
    /// Which kind of function is being bound (`FunctionType`).
    pub function_type: DictString,
    /// Serialized Arrow schema of the input table (`None` for table functions with no input).
    pub input_schema: Option<Bytes>,
    /// Serialized DuckDB session settings relevant to the function.
    pub settings: Option<Bytes>,
    /// Serialized resolved secret values the function declared it needs.
    pub secrets: Option<Bytes>,
    /// Opaque per-attach catalog session token (bytes) echoed back so the worker can scope
    /// catalog state to the attachment; `None` outside a catalog context.
    pub attach_opaque_data: Option<Bytes>,
    /// Opaque DuckDB transaction handle (bytes); `None` when not inside a transaction.
    pub transaction_opaque_data: Option<Bytes>,
    /// True when `secrets` carries already-resolved values, so the worker should not re-resolve
    /// them.
    pub resolved_secrets_provided: bool,
    /// Unit of the time-travel `AT (TIMESTAMP|VERSION ...)` clause for this scan, threaded
    /// through from DuckDB's per-reference bind; `None` when the scan has no AT clause. NOTE:
    /// for inline-bound (function-backed) tables the actual on_bind RPC runs once at attach
    /// with no AT, so this is `None` there; the per-scan AT is carried on the bind request
    /// embedded in each InitRequest, so functions should read it at init via
    /// `params.init_call.bind_call.at_value` (or the `ProcessParams.at_value` accessor), not at
    /// on_bind.
    pub at_unit: Option<String>,
    /// Value of the time-travel `AT` clause for this scan; `None` when the scan has no AT
    /// clause. See `at_unit` for the inline-bind caveat.
    pub at_value: Option<String>,
    /// The `COPY ... FROM` context (source format + path); `None` unless this bind/init opens a
    /// COPY-FROM scan.
    pub copy_from: Option<CopyFromContext>,
    /// The `COPY ... TO` context (destination format + path); `None` unless this bind/init
    /// opens a COPY-TO sink.
    pub copy_to: Option<CopyToContext>,
    /// Catalog schema that owns the function being bound. Set by the DuckDB extension from the
    /// schema entry the function was registered into, so a name registered in two schemas
    /// resolves to the right implementation. `None` for non-catalog callers (the legacy
    /// `Worker.functions` list), where lookup falls back to bare name.
    pub schema_path: Option<Vec<String>>,
    /// Resolved name of each logical argument, aligned with the complete pre-execution argument
    /// order. Fixed parameters use their declared names, unnamed varargs contain `None`, and
    /// named varargs retain the caller-provided name. `None` means names are unavailable.
    pub argument_names: Option<Vec<Option<String>>>,
    /// Where the externalized arguments live, when `arguments` is `None` (protocol 3.4 argument
    /// references). Always the last field.
    pub arguments_location: Option<ArgumentsLocation>,
}

impl BindRequest {
    /// Exactly one of `arguments` and `arguments_location` must be set; anything
    /// else is `invalid_bind_request` (`INVALID_ARGUMENT`).
    pub fn validate_arguments(&self) -> ::vgi_rpc::Result<()> {
        if self.arguments.is_some() == self.arguments_location.is_some() {
            return Err(::vgi_rpc::RpcError::value_error(
                "BindRequest must set exactly one of 'arguments' and 'arguments_location'",
            )
            .with_status(::vgi_rpc::Code::InvalidArgument, "invalid_bind_request"));
        }
        if let Some(location) = &self.arguments_location {
            location.validate()?;
        }
        Ok(())
    }
}

/// Consolidated init request for all function types.
///
/// For secondary init requests, `execution_id` and `init_opaque_data` are set; use
/// `is_secondary` to distinguish.
///
/// Derived schema must equal `generated::protocol_schemas::init_request_schema()`.
#[derive(Debug, Clone, VgiArrow)]
pub struct InitRequest {
    /// The originating `BindRequest` (function name, arguments, schemas).
    pub bind_call: Nested<BindRequest>,
    /// Serialized Arrow schema of the rows the function produces.
    pub output_schema: Bytes,
    /// Opaque per-bind state the worker returned from bind(), threaded back into later calls.
    /// Wire-facing bytes the framework produced from the typed `BindResult.opaque_data`;
    /// consumers reconstruct via `MyConcreteDataclass.deserialize_from_bytes(raw)`. See
    /// `BindResponse.opaque_data` in vgi/invocation.py for the full contract rationale.
    pub bind_opaque_data: Option<Bytes>,
    /// Column indices DuckDB wants projected from the function's output; `None` for scalar
    /// functions or when no projection pushdown.
    pub projection_ids: Option<Vec<i64>>,
    /// Serialized filter predicates DuckDB pushed down to the scan; `None` when no filters
    /// apply.
    pub pushdown_filters: Option<LargeBytes>,
    /// Serialized join-key batches pushed down for join filtering; `None` when not applicable.
    pub join_keys: Option<Vec<LargeBytes>>,
    /// Split tokens to redeem in this init, or None for an ordinary whole-scan init. Usually
    /// one; a client that bin-packs sends a whole group and expects them concatenated in the
    /// order given.
    pub split_tokens: Option<Vec<LargeBytes>>,
    /// Plain fetch limit, or None. NOT `order_by_limit`, which is a field of the Top-N hint.
    /// DuckDB cannot supply this; DataFusion can.
    pub row_limit: Option<i64>,
    /// For table-in-out functions, which init phase (INPUT / FINALIZE / buffering) this request
    /// opens; `None` for other function types.
    pub phase: Option<DictString>,
    /// For a buffered-table finalize stream, which state_id this stream serves. Required when
    /// `phase=TABLE_BUFFERING_FINALIZE`, `None` otherwise. Opaque bytes — the worker chose the
    /// encoding when its combine() returned the finalize_state_ids list.
    pub finalize_state_id: Option<Bytes>,
    /// Identifier for one query execution, stable across the coordinator and any secondary
    /// workers; keys worker-owned state. `None` for global init, set for secondary init.
    pub execution_id: Option<Bytes>,
    /// Opaque per-init state threaded back into the stream; same producer/wire/consumer
    /// contract as `bind_opaque_data`.
    pub init_opaque_data: Option<Bytes>,
    /// Stable, client-owned identity of the streaming table-in-out substream this request opens
    /// (per DuckDB PipelineExecutor). Rides every InitRequest a substream's worker builds —
    /// INPUT and FINALIZE — so a worker can locate that substream's accumulated state even when
    /// an HTTP load balancer routes its init / process / finalize to different backends. `None`
    /// for non-substream function types.
    pub substream_id: Option<Bytes>,
    /// Column name of the order-pushdown hint from DuckDB's RowGroupPruner optimizer; `None`
    /// when no hint.
    pub order_by_column_name: Option<String>,
    /// Sort direction of the order-pushdown hint; `None` when no hint.
    pub order_by_direction: Option<DictString>,
    /// Null-ordering of the order-pushdown hint; `None` when no hint.
    pub order_by_null_order: Option<DictString>,
    /// Row limit of the order-pushdown hint; `None` when no hint.
    pub order_by_limit: Option<i64>,
    /// Sample percentage of the TABLESAMPLE pushdown hint from DuckDB's SamplingPushdown
    /// optimizer; `None` when no hint.
    pub tablesample_percentage: Option<f64>,
    /// Sample seed of the TABLESAMPLE pushdown hint; `None` when no hint.
    pub tablesample_seed: Option<i64>,
}

impl InitRequest {
    /// `bind_call` decoded on first access; a decode error names `InitRequest.bind_call`.
    pub fn bind_call_value(&self) -> ::vgi_rpc::Result<&BindRequest> {
        self.bind_call.get_at("InitRequest.bind_call")
    }
}

